use std::{fs::{self,OpenOptions},io::{Read,Write},os::unix::fs::{MetadataExt,OpenOptionsExt,PermissionsExt,symlink},path::Path};

// The private managed directory makes the command independent of a moved app
// bundle or temporary AppImage mount; never replace a user's existing command.
pub fn install(home:&Path, executable:&Path)->Result<(),String>{
 if !executable.is_file(){return Err("Командная строка Atlas не установлена".into())}
 let uid=unsafe{libc::geteuid()};let local=home.join(".local");let bin=local.join("bin");let share=local.join("share");let managed=share.join("atlas-agent");
 for dir in [&local,&bin,&share] {match fs::create_dir(dir){Ok(())=>fs::set_permissions(dir,fs::Permissions::from_mode(0o700)).map_err(|e|e.to_string())?,Err(e) if e.kind()==std::io::ErrorKind::AlreadyExists=>{},Err(e)=>return Err(e.to_string())};let meta=fs::symlink_metadata(dir).map_err(|e|e.to_string())?;if !meta.is_dir()||meta.uid()!=uid||meta.mode()&0o022!=0{return Err("Небезопасный каталог команд".into())}}
 let created=match fs::create_dir(&managed){Ok(())=>true,Err(e) if e.kind()==std::io::ErrorKind::AlreadyExists=>false,Err(e)=>return Err(e.to_string())};
 if created {fs::set_permissions(&managed,fs::Permissions::from_mode(0o700)).map_err(|e|e.to_string())?;let mut f=OpenOptions::new().write(true).create_new(true).mode(0o600).custom_flags(libc::O_NOFOLLOW).open(managed.join(".atlas-owned")).map_err(|e|e.to_string())?;f.write_all(b"atlas-agent-v1\n").map_err(|e|e.to_string())?;}
 let meta=fs::symlink_metadata(&managed).map_err(|e|e.to_string())?;if !meta.is_dir()||meta.uid()!=uid||meta.mode()&0o077!=0{return Err("Небезопасный каталог CLI".into())}
 let marker=OpenOptions::new().read(true).custom_flags(libc::O_NOFOLLOW).open(managed.join(".atlas-owned")).map_err(|_|"Нет подтверждения каталога CLI")?;let m=marker.metadata().map_err(|e|e.to_string())?;let mut contents=String::new();marker.take(64).read_to_string(&mut contents).map_err(|e|e.to_string())?;if !m.is_file()||m.uid()!=uid||m.nlink()!=1||m.mode()&0o077!=0||contents!="atlas-agent-v1\n"{return Err("Небезопасный каталог CLI".into())}
 let target=managed.join("atlas-agent");let link=bin.join("atlas-agent");if let Ok(m)=fs::symlink_metadata(&link){if !m.file_type().is_symlink()||fs::read_link(&link).ok().as_deref()!=Some(target.as_path()){return Err("Команда atlas-agent уже существует и не была заменена".into())}}
 // Random names avoid stale files from a previous process with the same PID.
 let mut random=[0u8;16];fs::File::open("/dev/urandom").and_then(|mut f|f.read_exact(&mut random)).map_err(|e|e.to_string())?;
 let suffix=random.iter().map(|b|format!("{b:02x}")).collect::<String>();let temp=managed.join(format!(".atlas-agent-{suffix}"));let mut out=OpenOptions::new().write(true).create_new(true).mode(0o700).custom_flags(libc::O_NOFOLLOW).open(&temp).map_err(|e|e.to_string())?;
 let result=(||->Result<(),String>{let mut input=fs::File::open(executable).map_err(|e|e.to_string())?;std::io::copy(&mut input,&mut out).map_err(|e|e.to_string())?;out.sync_all().map_err(|e|e.to_string())?;fs::rename(&temp,&target).map_err(|e|e.to_string())?;Ok(())})();if result.is_err(){let _=fs::remove_file(&temp);}result?;
 match symlink(&target,&link){Ok(())=>Ok(()),Err(e) if e.kind()==std::io::ErrorKind::AlreadyExists&&fs::read_link(&link).ok().as_deref()==Some(target.as_path())=>Ok(()),Err(e)=>Err(e.to_string())}
}
#[cfg(test)] mod tests {use super::*;#[test]fn relocation_updates_managed_copy_without_overwriting_user_command(){let dir=std::env::temp_dir().join(format!("atlas-cli-install-{}",std::process::id()));fs::create_dir(&dir).unwrap();let first=dir.join("old-app");fs::write(&first,b"v1").unwrap();install(&dir,&first).unwrap();let stale=dir.join(".local/share/atlas-agent").join(format!(".atlas-agent-{}",std::process::id()));fs::write(&stale,b"stale").unwrap();fs::remove_file(first).unwrap();let next=dir.join("new-app");fs::write(&next,b"v2").unwrap();install(&dir,&next).unwrap();let bin=dir.join(".local/bin/atlas-agent");assert_eq!(fs::read(&bin).unwrap(),b"v2");assert_eq!(fs::read(&stale).unwrap(),b"stale");fs::remove_file(&bin).unwrap();fs::write(&bin,b"user command").unwrap();assert!(install(&dir,&next).is_err());assert_eq!(fs::read(&bin).unwrap(),b"user command");fs::remove_dir_all(dir).unwrap();}}
